mapper.select:
SELECT 
FROM room r
WHERE r.room_id = #{roomId}

SELECT room_id
FROM direct_room_pair
WHERE user_min = #{userMin} AND user_max = #{userMax}

SELECT last_seq
FROM room
WHERE room_id = #{roomId}

SELECT ,
       rm.last_seq_copy, rm.last_msg_type, rm.last_msg_preview, rm.last_msg_at,
       rm.last_read_seq, rm2.user_id AS peer_user_id
FROM room_member rm
JOIN room r ON r.room_id = rm.room_id
JOIN room_member rm2 ON rm2.room_id = rm.room_id AND rm2.user_id != #{userId}
WHERE rm.user_id = #{userId}
  AND rm.hidden_at IS NULL
ORDER BY rm.last_msg_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM room_member
WHERE room_id = #{roomId}

mapper.update:
UPDATE room_member
SET last_read_seq = #{lastReadSeq},
    update_time   = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}
  AND last_read_seq < #{lastReadSeq}

UPDATE room_member
SET hidden_at   = #{hiddenAt},
    update_time = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}

mapper.select:
SELECT 
FROM message m
WHERE m.room_id = #{roomId} AND m.seq = #{seq}

SELECT 
FROM message m
WHERE m.room_id = #{roomId} AND m.client_msg_id = #{clientMsgId}

SELECT 
FROM message m
WHERE m.msg_id = #{messageId}

mapper.update:
UPDATE room_member
SET last_msg_preview = #{preview},
    update_time      = NOW()
WHERE room_id = #{roomId}
  AND last_seq_copy = #{seq}

mapper.select:
SELECT 
FROM message m
WHERE m.room_id = #{roomId}

  AND m.seq < #{beforeSeq}

ORDER BY m.seq DESC
LIMIT #{limit}

SELECT t.delivery_seq, 
FROM timeline t
JOIN message m ON m.msg_id = t.msg_id
WHERE t.user_id = #{userId}
  AND t.delivery_seq > #{afterDeliverySeq}
ORDER BY t.delivery_seq ASC
LIMIT #{limit}

SELECT seq
FROM user_seq
WHERE user_id = #{userId}
